Question:
 ActiveOnly => [.. Questions.Where(Q => Q.IsEnabled)];

    public IReadOnlyList InActiveOnly => [.. Questions.Where(Q => !Q.IsEnabled)];

    public IReadOnlyList MatchesCategories(ImmutableHashSet? Categories)
    {
        ArgumentNullException.ThrowIfNull(Categories);
        return Categories.Count == 0 ? [.. Questions] : [.. Questions.Where(Q => Categories.Contains(Q.Category))];
    }

    public Question WithFilter(Filter? filter) => filter is not null
                ? new(Question.IsEnabled, Question.Text, Question.Filename, Question.Category, filter)
                : Question;

        public Question ToActiveOrDisabledQuestion() => Question.IsEnabled
                ? Question.IsActive(Question.Text, Question.Filename, Question.Category)
                : Question.IsDisabled(Question.Text, Question.Filename, Question.Category);
    }
}
